style.css:
/* Base page background and font */
html, body {
  background-color: #121212 !important;   /* popular dark grey base */
  color: #E8E8E8 !important;             /* soft off‑white text */
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont,
               "Segoe UI", Roboto, sans-serif !important;
  line-height: 1.7 !important;
}

/* Main content area (answer text) */
main, [class*="conversation"], [class*="message"],
[class*="content"], [data-testid*="message"] {
  background-color: #121212 !important;
  color: #E8E8E8 !important;
  font-size: 16px !important;
  line-height: 1.8 !important;
  max-width: 800px !important;     /* comfortable reading width */
  margin: 0 auto !important;
}

/* Headings: slightly warmer and brighter */
h1, h2, h3, h4, h5, h6 {
  color: #F5E8D8 !important;   /* warm beige */
  font-weight: 600 !important;
}

/* Links: subtle blue accent, lighter on hover */
a {
  color: #7FB8FF !important;
  text-decoration: none !important;
}

a:hover {
  color: #BEDAFF !important;
  text-decoration: underline !important;
}

/* Bold text: soft yellow */
b, strong {
  color: #F4D47C !important;   /* soft warm yellow */
  font-weight: 600 !important;
}

/* Italic text: soft orange */
i, em {
  color: #FFB27C !important;   /* soft warm orange */
  font-style: italic !important;
}

/* Bold + italic together: blend of both (slightly deeper orange-gold) */
b i, b em, strong i, strong em,
i b, em b, i strong, em strong {
  color: #F7C46A !important;
  font-weight: 650 !important;
  font-style: italic !important;
}

/* Sidebar and header */
header, nav, [class*="sidebar"] {
  background-color: #1C1C1E !important;  /* popular dark UI grey */
  color: #E8E8E8 !important;
}

/* Input box / composer */
textarea, input, [contenteditable="true"],
[class*="composer"], [class*="input"] {
  background-color: #1C1C1E !important;
  color: #E8E8E8 !important;
  border-radius: 8px !important;
  border: 1px solid #2A2A2A !important;
}

/* Code blocks */
pre, code {
  font-family: "JetBrains Mono", "Fira Code", Menlo, Monaco, monospace !important;
  background-color: #1E1E1E !important;
  color: #F5F5F5 !important;
}

/* Lists */
ul, ol, li {
  line-height: 1.8 !important;
}
